def ensure_template():
    try:
        return client().create_template(request={"parent": gcp.PARENT, "template_id": TEMPLATE_ID, "template": {"filter_config": {
            "pi_and_jailbreak_filter_settings": {"filter_enforcement": "ENABLED", "confidence_level": "MEDIUM_AND_ABOVE"},
